207	  /**
208	   * Lists insights with optional scope/category/tags/project_slug filters and pagination.
209	   *
210	   * Filters are applied in this order: store selection (scope/project_slug) → category →
211	   * tags → offset → limit.
212	   *
213	   * @param filters - Scope, category, tags, project_slug filters; limit and offset for pagination
214	   * @returns Filtered and paginated insight array
215	   */
216	  async listInsights(filters: {
217	    scope?: InsightScope;
218	    category?: string;
219	    tags?: string[];
220	    project_slug?: string;
221	    limit?: number;
222	    offset?: number;
223	  }): Promise<Insight[]> {
224	    const { limit, offset = 0, tags: tagFilter, ...loadFilters } = filters;
225	
226	    let insights = await this._loadInsights(loadFilters);
227	
228	    if (tagFilter && tagFilter.length > 0) {
229	      insights = insights.filter((insight) =>
230	        tagFilter.every((tag) => insight.tags.includes(tag))
231	      );
232	    }
233	
234	    return insights.slice(offset, limit !== undefined ? offset + limit : undefined);
235	  }
